INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM209CCIX', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A linear function $f$ satisfies $f(0) = 13$ and $f(1) = 9$. What is $f(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$7$"},{"key":"D","text":"$33$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{9 - 13}{1 - 0} = -4$, and the $y$-intercept is $13$, so $f(x) = -4x + 13$. Therefore $f(5) = -4(5) + 13 = -20 + 13 = -7$. The value $-3$ results from computing $f(4)$ instead of $f(5)$, a misread of the input. The value $7$ is a sign error, taking the absolute value of $-7$. The value $33$ comes from using a slope of $+4$ instead of $-4$, yielding $4(5) + 13 = 33$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20SQ00T', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line in the $xy$-plane passes through the points $(2, 17)$ and $(6, 41)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'The slope is $(41 - 17) \\div (6 - 2) = 24 \\div 4 = 6$. Using point $(2, 17)$: $17 = 6(2) + b$, so $b = 17 - 12 = 5$. The $y$-intercept is 5.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM218ULGW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A biologist collected data on the age (in months) and mass (in grams) of a sample of 14 specimens of a species. The equation of the least-squares regression line is $\\hat{y} = 3.47x + 81.2$ with $r = 0.91$. One specimen was 18 months old and had a mass of 152 grams. What is the residual, in grams, for this specimen?', NULL, $lyceon_json$[{"key":"A","text":"$8.34$"},{"key":"B","text":"$-8.34$"},{"key":"C","text":"$70.8$"},{"key":"D","text":"$-70.8$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted mass for an 18-month-old specimen is $\\hat{y} = 3.47(18) + 81.2 = 62.46 + 81.2 = 143.66$ grams. The residual is observed minus predicted: $152 - 143.66 = 8.34$ grams. The distractor $-8.34$ reverses the residual formula by computing predicted minus observed. The distractor $70.8$ computes $152 - 81.2$, subtracting only the intercept and ignoring the slope term. The distractor $-70.8$ applies the sign reversal to that same incorrect calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21C6TNZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a circumference of $8\\pi$. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$4\\pi$"},{"key":"B","text":"$8\\pi$"},{"key":"C","text":"$16\\pi$"},{"key":"D","text":"$64\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The circumference formula is $C = 2\\pi r$. Setting $2\\pi r = 8\\pi$ gives $r = 4$. The area is $A = \\pi r^2 = \\pi(4)^2 = 16\\pi$. The distractor $4\\pi$ uses $\\pi r$ instead of $\\pi r^2$, omitting the squaring step. The distractor $8\\pi$ simply repeats the circumference value. The distractor $64\\pi$ uses the diameter ($8$) instead of the radius, computing $\\pi(8)^2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21CWMJ8', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'If $-4 < 3 - \\frac{x}{2} \\leq 11$, what is the greatest integer value of $x$ that satisfies the compound inequality?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'Starting with $-4 < 3 - \\frac{x}{2} \\leq 11$, subtract $3$ from all parts: $-7 < -\\frac{x}{2} \\leq 8$. Multiply all parts by $-2$ and reverse both inequality signs: $-16 \\leq x < 14$. The greatest integer value of $x$ strictly less than $14$ is $13$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21JBPW3', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the value of $x$ that satisfies $\\frac{2x + 9}{3} = \\frac{4x - 1}{5}$?', NULL, $lyceon_json$[{"key":"A","text":"$-24$"},{"key":"B","text":"$8$"},{"key":"C","text":"$21$"},{"key":"D","text":"$24$"}]$lyceon_json$::jsonb, 'D', NULL, E'Cross-multiplying gives $5(2x + 9) = 3(4x - 1)$, which expands to $10x + 45 = 12x - 3$. Subtracting $10x$ from both sides yields $45 = 2x - 3$, and adding 3 gives $48 = 2x$, so $x = 24$. The value $-24$ results from a sign error when moving terms across the equation. The value $21$ comes from an arithmetic slip such as computing $45 - 3 = 42$ instead of $45 + 3 = 48$. The value $8$ results from an equation setup error such as failing to cross-multiply correctly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21OEBBB', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'Which of the following ordered pairs $(x, y)$ satisfies the equation $3x + 7y = 41$?', NULL, $lyceon_json$[{"key":"A","text":"$(2, 5)$"},{"key":"B","text":"$(3, 7)$"},{"key":"C","text":"$(5, 2)$"},{"key":"D","text":"$(7, 3)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $(2, 5)$: $3(2) + 7(5) = 6 + 35 = 41$, which equals the right side. Substituting $(3, 7)$: $3(3) + 7(7) = 9 + 49 = 58 \\neq 41$, so this pair reflects an equation setup error. Substituting $(5, 2)$: $3(5) + 7(2) = 15 + 14 = 29 \\neq 41$; this pair swaps the correct coordinates, a misread of which value corresponds to $x$ and $y$. Substituting $(7, 3)$: $3(7) + 7(3) = 21 + 21 = 42 \\neq 41$, an arithmetic slip that is off by one.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21SCC5H', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $7(3x - 4) + 5x$?', NULL, $lyceon_json$[{"key":"A","text":"$26x - 28$"},{"key":"B","text":"$26x - 4$"},{"key":"C","text":"$21x - 28$"},{"key":"D","text":"$22x - 28$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $7(3x - 4) + 5x = 21x - 28 + 5x = 26x - 28$. The expression $26x - 4$ results from failing to distribute the $7$ to the $-4$ term. The expression $21x - 28$ omits the $+5x$ term entirely. The expression $22x - 28$ comes from an arithmetic error when adding $21x + 5x$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM243VHIN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows a strong positive linear association between hours of sunlight per day and the height of a plant in centimeters. The line of best fit is $y = 2.7x + 4.1$, where $x$ is hours of sunlight per day and $y$ is plant height in centimeters. What does the slope of the line represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"The predicted increase in plant height, in centimeters, for each additional hour of sunlight per day"},{"key":"B","text":"The predicted plant height, in centimeters, when there are zero hours of sunlight"},{"key":"C","text":"The predicted number of hours of sunlight needed for the plant to grow 1 centimeter"},{"key":"D","text":"The predicted total height, in centimeters, after one day of sunlight"}]$lyceon_json$::jsonb, 'A', NULL, E'In the equation $y = 2.7x + 4.1$, the slope 2.7 represents the predicted change in $y$ (plant height in centimeters) for each one-unit increase in $x$ (hours of sunlight per day). The distractor describing plant height at zero sunlight confuses the slope with the y-intercept (4.1). The distractor about hours needed per centimeter of growth inverts the slope relationship. The distractor about total height after one day confuses the rate of change with a cumulative output.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24BHM71', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{9x^2 - 49}{3x + 7}$ for $x \\neq -\\frac{7}{3}$?', NULL, $lyceon_json$[{"key":"A","text":"$3x + 7$"},{"key":"B","text":"$3x - 7$"},{"key":"C","text":"$9x - 7$"},{"key":"D","text":"$x - 7$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $9x^2 - 49$ is a difference of squares: $(3x)^2 - 7^2 = (3x + 7)(3x - 7)$. Dividing by $(3x + 7)$ gives $3x - 7$. Choosing $3x + 7$ reflects a sign error in the factorization. Choosing $9x - 7$ shows a failure to recognize the difference-of-squares pattern. Choosing $x - 7$ results from incorrectly simplifying the coefficients after factoring.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2584NJJ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $29°$ and the measure of angle $Q$ is $114°$. What is the measure of the exterior angle at vertex $R$?', NULL, $lyceon_json$[{"key":"A","text":"$37°$"},{"key":"B","text":"$66°$"},{"key":"C","text":"$143°$"},{"key":"D","text":"$151°$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the exterior angle theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles: $29° + 114° = 143°$. The distractor $37°$ is the interior angle at $R$ (found by $180° - 29° - 114° = 37°$), which answers the wrong question. The distractor $66°$ comes from subtracting only one interior angle from $180°$ ($180° - 114° = 66°$). The distractor $151°$ results from an arithmetic error when summing the remote interior angles.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2632JFH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university researcher randomly selects 500 undergraduate students and randomly assigns them to two groups. Group A attends weekly study-skills workshops for one semester, while Group B receives no intervention. At the end of the semester, Group A has a mean GPA of $3.41$ and Group B has a mean GPA of $3.17$. The difference is statistically significant at the $p < 0.01$ level. A college administrator wants to apply these results to all undergraduate students at the university. Which of the following is the most important limitation of generalizing this finding?', NULL, $lyceon_json$[{"key":"A","text":"The study did not use random assignment, so causation cannot be established."},{"key":"B","text":"The difference in GPA could be due to the placebo effect, since Group B knew they were not receiving the workshops."},{"key":"C","text":"The sample was drawn from a single university, so the results may not generalize to students at other universities."},{"key":"D","text":"A $p$-value less than $0.01$ is not small enough to draw meaningful conclusions."}]$lyceon_json$::jsonb, 'C', NULL, E'The study used random assignment, so it can establish a causal relationship between the workshops and GPA improvement within the study population. However, the administrator wants to generalize beyond the university. Since the sample was drawn entirely from one university, the results may not apply to students at different institutions with different demographics, academic cultures, or support systems. The claim that random assignment was not used directly contradicts the study description. While the placebo effect is a valid concern in experimental design, the question asks about the most important limitation of generalizing the finding to all undergraduates, and the scope of the sample is the primary limitation. A $p$-value less than $0.01$ is a conventional threshold for strong statistical significance, so dismissing it as insufficient reflects a misunderstanding of hypothesis testing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM266DQ1K', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'The equations $5x - 3y = 17$ and $kx + 9y = -51$ represent the same line in the $xy$-plane. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-15$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$3$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'A', NULL, E'For the two equations to represent the same line, one must be a scalar multiple of the other. Comparing $y$-coefficients: $-3 \\cdot c = 9$ gives $c = -3$. Checking constants: $17 \\cdot (-3) = -51$, which matches. Therefore $k = 5 \\cdot (-3) = -15$. The value $15$ results from a sign error, using $c = 3$ instead of $c = -3$. The value $-5$ comes from a concept gap such as simply negating the coefficient of $x$ from the first equation. The value $3$ comes from misreading the ratio as $9 / (-3) = -3$ and then confusing it with $|-3| = 3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26LV6L9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'Which of the following is the equation of a circle in the $xy$-plane with center $(-7, 4)$ and radius $\\sqrt{26}$?', NULL, $lyceon_json$[{"key":"A","text":"$(x - 7)^2 + (y + 4)^2 = 26$"},{"key":"B","text":"$(x + 7)^2 + (y - 4)^2 = 26$"},{"key":"C","text":"$(x + 7)^2 + (y - 4)^2 = \\sqrt{26}$"},{"key":"D","text":"$(x - 7)^2 + (y + 4)^2 = 676$"}]$lyceon_json$::jsonb, 'B', NULL, E'The standard form of a circle with center $(h, k)$ and radius $r$ is $(x - h)^2 + (y - k)^2 = r^2$. With center $(-7, 4)$ and radius $\\sqrt{26}$: $(x - (-7))^2 + (y - 4)^2 = (\\sqrt{26})^2$, which simplifies to $(x + 7)^2 + (y - 4)^2 = 26$. The distractor $(x - 7)^2 + (y + 4)^2 = 26$ reverses the signs on both center coordinates. The distractor with $\\sqrt{26}$ on the right side forgets to square the radius. The distractor with $676$ both reverses the signs and squares $26$ instead of $\\sqrt{26}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26XF1XG', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $y$ in the solution to the system of equations below?$$\\begin{cases} x + y = 17 \\\\ x - y = 3 \\end{cases}$$', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$10$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding the two equations eliminates $y$: $2x = 20$, so $x = 10$. Substituting back into $x + y = 17$ gives $y = 7$. The value $10$ is the $x$-value, not the $y$-value the question asks for. The value $14$ comes from incorrectly adding $7 + 7$. The value $5$ results from a subtraction error when computing $17 - 10$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM273MG8O', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 3x^2 - 7$. What is the value of $g(-2)$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$-19$"},{"key":"C","text":"$19$"},{"key":"D","text":"$-5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = -2$: $g(-2) = 3(-2)^2 - 7 = 3(4) - 7 = 12 - 7 = 5$. The value $-19$ results from incorrectly computing $(-2)^2$ as $-4$ instead of $4$, giving $3(-4) - 7 = -19$. The value $19$ comes from adding $12 + 7$ instead of subtracting. The value $-5$ results from computing $3(2) - 7 = -1$ or similar confusion about squaring a negative number.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM276188X', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In right triangle $PQR$ with the right angle at $Q$, altitude $QS$ is drawn to the hypotenuse $PR$. If $PS = 4$ and $SR = 9$, what is the length of $QS$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'When an altitude is drawn from the right angle to the hypotenuse of a right triangle, the altitude is the geometric mean of the two segments of the hypotenuse. Therefore $QS^2 = PS \\times SR = 4 \\times 9 = 36$, which gives $QS = 6$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27VR9HY', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many real solutions does the equation $3x^2 - 14x + 19 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"Infinitely many"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is $b^2 - 4ac = (-14)^2 - 4(3)(19) = 196 - 228 = -32$. Since the discriminant is negative, the equation has no real solutions. Choosing $1$ reflects confusing a negative discriminant with a zero discriminant, which would produce one repeated root. Choosing $2$ ignores the discriminant entirely, assuming all quadratics have two real roots. Choosing infinitely many confuses a quadratic equation with an identity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM299S1WV', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A delivery service charges a flat fee of 29 dollars plus 3 dollars per pound for shipping a package. If a customer has a budget of at most 71 dollars for shipping, which inequality represents the number of pounds $p$ the customer can ship?', NULL, $lyceon_json$[{"key":"A","text":"$3p + 29 \\leq 71$"},{"key":"B","text":"$3p + 29 \\geq 71$"},{"key":"C","text":"$29p + 3 \\leq 71$"},{"key":"D","text":"$3p - 29 \\leq 71$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the flat fee of 29 dollars plus 3 dollars per pound, giving $3p + 29$. Since the customer can spend at most 71 dollars, the inequality is $3p + 29 \\leq 71$. Using $\\geq$ instead of $\\leq$ reverses the budget constraint. Writing $29p + 3$ swaps the per-pound rate and the flat fee. Subtracting 29 instead of adding it misrepresents the flat fee as a discount.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AI5XXI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'The price of a collectible increased by $40\\%$ during the first year and then decreased by $15\\%$ during the second year. If the price at the end of the second year was 1,071 dollars, what was the original price, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$900$"},{"key":"B","text":"$856.80$"},{"key":"C","text":"$765$"},{"key":"D","text":"$1,000$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let the original price be $p$. After a $40\\%$ increase, the price is $1.4p$. After a $15\\%$ decrease, the price is $1.4p \\times 0.85 = 1.19p$. Setting $1.19p = 1071$ gives $p = \\frac{1071}{1.19} = 900$ dollars. The distractor 856.80 results from dividing 1071 by 1.25, treating the net change as $+25\\%$ ($40\\% - 15\\%$) instead of applying successive multipliers. The distractor 765 results from incorrectly reversing the operations. The distractor 1,000 is a rough estimate that ignores the compounding of percentages.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BYIG20', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A printer produces 37 pages in 4 minutes. At this constant rate, how many minutes will it take to print 259 pages?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '28', ARRAY['28'], E'The rate is $\\frac{37 \\text{ pages}}{4 \\text{ minutes}}$. To find the time for 259 pages, set up the proportion $\\frac{37}{4} = \\frac{259}{t}$, giving $t = \\frac{259 \\times 4}{37} = \\frac{1036}{37} = 28$ minutes. Since $259 = 37 \\times 7$, the printer needs $4 \\times 7 = 28$ minutes.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C56JIE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'The system of equations $y = x^2 - 3x - 1$ and $y = 2x + 5$ has two solutions. What is the $y$-coordinate of the solution with $x > 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'Setting the equations equal: $x^2 - 3x - 1 = 2x + 5$. Rearranging: $x^2 - 5x - 6 = 0$. Factoring: $(x - 6)(x + 1) = 0$, so $x = 6$ or $x = -1$. The solution with $x > 0$ has $x = 6$. Substituting into $y = 2x + 5$ gives $y = 2(6) + 5 = 17$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C8CX6I', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A cylindrical tank with a radius of $3$ feet is being filled with water at a constant rate of $6\\pi$ cubic feet per minute. How many minutes will it take to fill the tank to a height of $14$ feet?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21', ARRAY['21'], E'The volume of a cylinder is $V = \\pi r^2 h$. The volume needed to fill the tank to a height of $14$ feet is $V = \\pi(3)^2(14) = \\pi(9)(14) = 126\\pi$ cubic feet. At a fill rate of $6\\pi$ cubic feet per minute, the time required is $\\frac{126\\pi}{6\\pi} = 21$ minutes.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D3F3LO', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'A plumber charges a flat fee of 47 dollars plus 31 dollars per hour of labor. If the total charge for a job was 233 dollars, how many hours of labor did the job require?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Let $h$ represent the number of hours. The total charge is $47 + 31h = 233$. Subtracting 47 from both sides gives $31h = 186$. Dividing by 31 yields $h = 6$. A common error is dividing 233 by 31 without first subtracting the flat fee, which gives approximately 7.5. Another error is subtracting 31 from 233 and dividing by 47, confusing which value is the rate and which is the flat fee.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D9R1IF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h(x) = -2(x + 3)^2 + 11$ models the height, in feet, of a ball $x$ seconds after it was thrown. What is the maximum height, in feet, the ball reaches?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$3$"},{"key":"C","text":"$29$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function is in vertex form $a(x - h)^2 + k$ with $a = -2$ and vertex at $(-3, 11)$. Since $a < 0$, the parabola opens downward, so the vertex represents a maximum. The maximum height is $11$ feet. The value $3$ comes from reading the $x$-coordinate of the vertex rather than the $y$-coordinate. The value $29$ results from incorrectly computing $-2(0 + 3)^2 + 11$ with a sign error to get $18 + 11 = 29$. The value $-7$ comes from evaluating at $x = 0$, giving $-2(9) + 11 = -7$, which is a point on the function but not the maximum.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E4CWQB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'The mean of 9 numbers is 46. When an additional number is included, the mean of all 10 numbers becomes 43. What is the value of the additional number?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '16', ARRAY['16'], E'The sum of the original 9 numbers is $9 \\times 46 = 414$. The sum of all 10 numbers is $10 \\times 43 = 430$. The additional number is $430 - 414 = 16$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E747UK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'The equation $x^2 + y^2 - 22x + 10y + 137 = 0$ represents a circle in the $xy$-plane. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'To find the radius, complete the square for both variables. Group terms: $(x^2 - 22x) + (y^2 + 10y) = -137$. Complete the square for $x$: $x^2 - 22x + 121 = (x - 11)^2$. Complete the square for $y$: $y^2 + 10y + 25 = (y + 5)^2$. Adding $121$ and $25$ to both sides: $(x - 11)^2 + (y + 5)^2 = -137 + 121 + 25 = 9$. The equation is now in standard form with $r^2 = 9$, so $r = 3$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E88ZIT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 400 voters in a city found that 172 support a proposed tax measure. The margin of error for the survey is $\\pm 4\\%$. Which of the following is the best estimate of the range for the percentage of all voters in the city who support the measure?', NULL, $lyceon_json$[{"key":"A","text":"$39\\%$ to $47\\%$"},{"key":"B","text":"$43\\%$ to $47\\%$"},{"key":"C","text":"$40\\%$ to $46\\%$"},{"key":"D","text":"$35\\%$ to $51\\%$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sample proportion is $\\frac{172}{400} = 0.43$, or $43\\%$. With a margin of error of $\\pm 4\\%$, the plausible range is $43\\% - 4\\% = 39\\%$ to $43\\% + 4\\% = 47\\%$. The range $43\\%$ to $47\\%$ only adds the margin of error in one direction. The range $40\\%$ to $46\\%$ uses an incorrect margin of $\\pm 3\\%$. The range $35\\%$ to $51\\%$ uses a margin of $\\pm 8\\%$, doubling the stated value.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F7AYQR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A class of 31 students took a quiz. The scores had the following frequency distribution: score 2 (3 students), score 4 (5 students), score 5 (7 students), score 6 (4 students), score 7 (6 students), score 8 (3 students), score 9 (2 students), score 10 (1 student). If the 3 students who scored 2 each improve their scores to 6 on a retake and the retake scores replace the originals, which of the following must be true?', NULL, $lyceon_json$[{"key":"A","text":"The mean increases and the median stays the same."},{"key":"B","text":"Both the mean and the median increase."},{"key":"C","text":"The mean increases and the median increases by 1."},{"key":"D","text":"The mean stays the same and the median increases."}]$lyceon_json$::jsonb, 'A', NULL, E'Originally the sum of scores is $2(3)+4(5)+5(7)+6(4)+7(6)+8(3)+9(2)+10(1) = 6+20+35+24+42+24+18+10 = 179$. The original mean is $\\frac{179}{31} \\approx 5.77$. After the change, the three scores of 2 become 6, adding $3 \\times 4 = 12$ to the sum, making it 191. The new mean is $\\frac{191}{31} \\approx 6.16$, so the mean increases. For the median (the 16th value when sorted), the original cumulative counts are: score 2 (3), score 4 (8), score 5 (15), score 6 (19). The 16th value falls at score 6. After the change, the cumulative counts become: score 4 (5), score 5 (12), score 6 (22). The 16th value is still score 6, so the median stays the same. The distractor stating both increase incorrectly assumes the median shifts. The distractor claiming the median increases by 1 miscounts the cumulative frequencies. The distractor stating the mean stays the same ignores that the total sum changes when low scores are replaced by higher ones.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GB4GCZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A class has 29 students. Of these, 13 play soccer and 9 play basketball. If 4 students play both sports, what is the probability that a randomly selected student plays soccer or basketball?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{18}{29}$"},{"key":"B","text":"$\\frac{22}{29}$"},{"key":"C","text":"$\\frac{13}{29}$"},{"key":"D","text":"$\\frac{26}{29}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using inclusion-exclusion, the number of students who play soccer or basketball is $13 + 9 - 4 = 18$. The probability is $\\frac{18}{29}$. The answer $\\frac{22}{29}$ adds $13 + 9 = 22$ without subtracting the overlap, double-counting students who play both sports. The answer $\\frac{13}{29}$ only accounts for soccer players. The answer $\\frac{26}{29}$ results from an arithmetic error such as computing $13 + 9 + 4 = 26$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GMHSUE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains 13 red marbles, 8 blue marbles, and 4 green marbles. If one marble is selected at random, what is the probability that the marble is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{8}{25}$"},{"key":"B","text":"$\\frac{8}{17}$"},{"key":"C","text":"$\\frac{4}{25}$"},{"key":"D","text":"$\\frac{13}{25}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is $13 + 8 + 4 = 25$. The probability of selecting a blue marble is the number of blue marbles divided by the total: $\\frac{8}{25}$. The fraction $\\frac{8}{17}$ incorrectly excludes the green marbles from the total. The fraction $\\frac{4}{25}$ gives the probability of selecting a green marble, not a blue one. The fraction $\\frac{13}{25}$ gives the probability of selecting a red marble.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HU8846', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at 130 dollars is on sale for 91 dollars. What is the percent decrease in price?', NULL, $lyceon_json$[{"key":"A","text":"$39\\%$"},{"key":"B","text":"$30\\%$"},{"key":"C","text":"$70\\%$"},{"key":"D","text":"$42.9\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The decrease is $130 - 91 = 39$ dollars. The percent decrease is $\\frac{39}{130} \\times 100 = 30\\%$. The distractor $39\\%$ confuses the dollar amount of the decrease with the percent decrease. The distractor $70\\%$ gives the sale price as a percentage of the original rather than the decrease. The distractor $42.9\\%$ incorrectly divides the decrease by the sale price ($\\frac{39}{91} \\approx 42.9\\%$) instead of the original price.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IHM0SB', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function $g$ is defined by $g(x) = mx + b$, where $m$ and $b$ are constants. If $g(3) = 22$ and $g(11) = -18$, what is the value of $g(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$2$"},{"key":"C","text":"$4$"},{"key":"D","text":"$42$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope is $m = \\frac{-18 - 22}{11 - 3} = \\frac{-40}{8} = -5$. Using $g(3) = 22$: $-5(3) + b = 22$, so $b = 37$ and $g(x) = -5x + 37$. Therefore $g(7) = -5(7) + 37 = -35 + 37 = 2$. Equivalently, since 7 is the midpoint of 3 and 11, $g(7) = \\frac{22 + (-18)}{2} = 2$. The value $-2$ is a sign error in the final subtraction. The value $4$ is an arithmetic slip, such as computing $22 + (-18) = 4$ without averaging. The value $42$ comes from using a slope of $+5$ instead of $-5$, reflecting a concept gap about the direction of change.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IIM1UN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher wants to determine whether a new fertilizer increases tomato plant yield. She randomly assigns 34 tomato plants to receive the new fertilizer and 34 tomato plants to receive a standard fertilizer, then measures the yield of each plant after 8 weeks. This study is best described as which of the following?', NULL, $lyceon_json$[{"key":"A","text":"A survey"},{"key":"B","text":"An observational study"},{"key":"C","text":"An experiment"},{"key":"D","text":"A census"}]$lyceon_json$::jsonb, 'C', NULL, E'Because the researcher randomly assigns plants to treatment groups (new fertilizer vs. standard fertilizer), this is an experiment. Random assignment of treatments is the defining feature that distinguishes an experiment from an observational study. A survey collects self-reported data from respondents without imposing a treatment. An observational study measures existing conditions without assigning treatments. A census attempts to collect data from every member of a population, which is not what is described here.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KMWWQS', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'If $13x - 27 = 64$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Adding 27 to both sides gives $13x = 91$. Dividing both sides by 13 gives $x = 7$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L3QJBC', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A farm sells two types of feed. Type P costs 11 dollars per bag and type Q costs 19 dollars per bag. A farmer buys a total of 9 bags and spends exactly 139 dollars. How many bags of type Q did the farmer buy?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $p$ be the number of type P bags and $q$ the number of type Q bags. Then $p + q = 9$ and $11p + 19q = 139$. Substituting $p = 9 - q$ gives $11(9 - q) + 19q = 139$, which simplifies to $99 + 8q = 139$, so $8q = 40$ and $q = 5$. Choosing $4$ results from a division error when solving $8q = 40$. Choosing $6$ comes from confusing the count of type Q bags with the count of type P bags. Choosing $3$ reflects an error in setting up the cost equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M2PXV1', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $x$ satisfies the inequality $9x - 17 > 46$?', NULL, $lyceon_json$[{"key":"A","text":"4"},{"key":"B","text":"6"},{"key":"C","text":"7"},{"key":"D","text":"8"}]$lyceon_json$::jsonb, 'D', NULL, E'Adding 17 to both sides gives $9x > 63$. Dividing both sides by 9 gives $x > 7$. The only value greater than 7 is 8. The value 7 fails because the inequality is strict (greater than, not greater than or equal to). The values 4 and 6 are both less than 7 and do not satisfy the inequality.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M64PWJ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a perimeter of $58$ meters and a width of $11$ meters. What is the area of the garden, in square meters?', NULL, $lyceon_json$[{"key":"A","text":"$198$"},{"key":"B","text":"$209$"},{"key":"C","text":"$319$"},{"key":"D","text":"$638$"}]$lyceon_json$::jsonb, 'A', NULL, E'The perimeter of a rectangle is $P = 2(l + w)$. Substituting: $58 = 2(l + 11)$, so $l + 11 = 29$ and $l = 18$. The area is $A = l \\times w = 18 \\times 11 = 198$ square meters. The distractor $209$ results from a calculation error of $19 \\times 11$. The distractor $319$ uses $29 \\times 11$, forgetting to divide the perimeter by $2$ before subtracting the width. The distractor $638$ multiplies the full perimeter by the width ($58 \\times 11$).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MY4155', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'After a $23\\%$ increase, the membership of a club is 369. What was the membership before the increase?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '300', ARRAY['300'], E'Let the original membership be $x$. After a $23\\%$ increase, the membership is $1.23x = 369$. Solving gives $x = \\frac{369}{1.23} = 300$. The original membership was 300.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N0AQQ7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $JKL$ with the right angle at $K$, $\\tan(J) = \\frac{5}{9}$. If the length of side $JK$ is $27$, what is the length of side $KL$?', NULL, $lyceon_json$[{"key":"A","text":"$12$"},{"key":"B","text":"$15$"},{"key":"C","text":"$3\\sqrt{106}$"},{"key":"D","text":"$45$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since the right angle is at $K$, side $JK$ is adjacent to angle $J$ and side $KL$ is opposite angle $J$. Using the tangent ratio: $\\tan(J) = \\frac{KL}{JK} = \\frac{5}{9}$. With $JK = 27$: $KL = 27 \\times \\frac{5}{9} = 15$. The distractor $12$ results from a multiplication error ($27 \\times \\frac{4}{9}$). The distractor $3\\sqrt{106}$ is the hypotenuse $JL = \\sqrt{27^2 + 15^2} = \\sqrt{954} = 3\\sqrt{106}$, answering the wrong question. The distractor $45$ comes from multiplying $27 \\times \\frac{5}{3}$, incorrectly simplifying the fraction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NWLSLN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'Two angles of a triangle are in the ratio $5:3$, and the third angle measures $44°$. What is the measure, in degrees, of the largest angle of the triangle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '85', ARRAY['85'], E'Let the two angles in the ratio $5:3$ be $5k$ and $3k$. Since the angles of a triangle sum to $180°$: $5k + 3k + 44 = 180$, so $8k = 136$ and $k = 17$. The three angles are $5(17) = 85°$, $3(17) = 51°$, and $44°$. The largest angle is $85°$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OO1WOK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the product of the solutions to $x^2 - 11x + 28 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '28', ARRAY['28'], E'The equation $x^2 - 11x + 28 = 0$ factors as $(x - 4)(x - 7) = 0$, giving solutions $x = 4$ and $x = 7$. The product of the solutions is $4 \\times 7 = 28$. By Vieta''s formulas, the product of the roots of $x^2 + bx + c = 0$ equals $c$, which here is $28$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PC080M', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'grid_in', E'A researcher models the relationship between the number of years since 2010, $x$, and the population of a town, in hundreds, $y$, using the equation $y = 1.9x + 23.3$. According to the model, in what year is the population predicted to first exceed 6,100?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2030', ARRAY['2030'], E'A population of 6,100 corresponds to $y = 61$ (since $y$ is in hundreds). Setting $1.9x + 23.3 = 61$ gives $1.9x = 37.7$, so $x = \\frac{37.7}{1.9} \\approx 19.84$. Since $x$ must be a whole number of years and the population must exceed 6,100 (not just equal it), the first such year corresponds to $x = 20$. The year is $2010 + 20 = 2030$. Checking: at $x = 19$, $y = 1.9(19) + 23.3 = 36.1 + 23.3 = 59.4$ (hundreds) = 5,940 < 6,100. At $x = 20$, $y = 1.9(20) + 23.3 = 38 + 23.3 = 61.3$ (hundreds) = 6,130 > 6,100.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PTMLUA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A fuel mixture requires diesel and biodiesel in a ratio of 13 to 3. A mechanic has 52 liters of diesel and 15 liters of biodiesel. She wants to use all of one fuel type and as much of the other as the ratio allows. What is the maximum total volume of the mixture, in liters, she can produce?', NULL, $lyceon_json$[{"key":"A","text":"$65$"},{"key":"B","text":"$67$"},{"key":"C","text":"$\\frac{256}{3}$"},{"key":"D","text":"$64$"}]$lyceon_json$::jsonb, 'D', NULL, E'Check both cases. Case 1: use all 52 liters of diesel. The required biodiesel is $52 \\times \\frac{3}{13} = 12$ liters. Since $12 < 15$, this is feasible. Total = $52 + 12 = 64$ liters. Case 2: use all 15 liters of biodiesel. The required diesel is $15 \\times \\frac{13}{3} = 65$ liters. Since $65 > 52$, this exceeds the available diesel and is not feasible. The maximum mixture is 64 liters. The distractor 65 results from the infeasible case of using all biodiesel without checking diesel availability. The distractor 67 adds the full diesel and biodiesel amounts without maintaining the ratio. The distractor $\\frac{256}{3}$ results from an algebraic error in computing the proportional amount.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q8NWVZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a diameter of $6$ inches and a height of $17$ inches. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$51\\pi$ cubic inches"},{"key":"B","text":"$102\\pi$ cubic inches"},{"key":"C","text":"$153\\pi$ cubic inches"},{"key":"D","text":"$612\\pi$ cubic inches"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h$. The diameter is $6$, so the radius is $3$. Substituting: $V = \\pi(3)^2(17) = \\pi(9)(17) = 153\\pi$ cubic inches. The distractor $51\\pi$ computes $\\pi(3)(17)$, forgetting to square the radius. The distractor $102\\pi$ uses the diameter instead of the radius, computing $\\pi(6)(17)$. The distractor $612\\pi$ squares the diameter instead of the radius, computing $\\pi(36)(17)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"unit_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QV92VS', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'grid_in', E'The system of equations $\\begin{cases} 5x - 2y = 41 \\\\ 3x + 7y = 0 \\end{cases}$ has the solution $(x, y)$. What is the value of $x + y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Multiply the first equation by $7$ and the second by $2$: $35x - 14y = 287$ and $6x + 14y = 0$. Adding these equations gives $41x = 287$, so $x = 7$. Substituting into $3(7) + 7y = 0$ yields $21 + 7y = 0$, so $y = -3$. Therefore $x + y = 7 + (-3) = 4$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SRC2H1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In right triangle $DEF$ with the right angle at $E$, $\\sin(D) = \\frac{7}{11}$. What is $\\cos(F)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{11}$"},{"key":"B","text":"$\\frac{4}{11}$"},{"key":"C","text":"$\\frac{6\\sqrt{2}}{11}$"},{"key":"D","text":"$\\frac{11}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'In a right triangle, the two acute angles are complementary: $D + F = 90°$. A fundamental identity states that $\\cos(F) = \\sin(90° - F) = \\sin(D)$. Therefore $\\cos(F) = \\frac{7}{11}$. The distractor $\\frac{4}{11}$ comes from incorrectly subtracting $7$ from $11$. The distractor $\\frac{6\\sqrt{2}}{11}$ is the value of $\\cos(D)$, not $\\cos(F)$, confusing which angle to evaluate. The distractor $\\frac{11}{7}$ incorrectly takes the reciprocal.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TQBLPA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a survey of 200 employees, 74 have a graduate degree and 126 do not. Of those with a graduate degree, 57 received a promotion. Of those without a graduate degree, 38 received a promotion. Given that a randomly selected employee received a promotion, what is the probability that the employee has a graduate degree?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{57}{200}$"},{"key":"B","text":"$\\frac{57}{74}$"},{"key":"C","text":"$\\frac{57}{95}$"},{"key":"D","text":"$\\frac{38}{95}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The total number of employees who received a promotion is $57 + 38 = 95$. The conditional probability that an employee has a graduate degree given that they received a promotion is $\\frac{57}{95}$. The answer $\\frac{57}{200}$ divides by the total number of employees rather than the number who received a promotion, finding the unconditional probability. The answer $\\frac{57}{74}$ divides by the total number of employees with a graduate degree, which gives the probability of promotion given a graduate degree rather than the reverse. The answer $\\frac{38}{95}$ gives the probability that a promoted employee does NOT have a graduate degree.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TR9A9P', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'For what value of $a$ does the equation $a(x - 4) + 7 = 3x + 2(x - 5)$ have no solution?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$3$"},{"key":"C","text":"$5$"},{"key":"D","text":"$\\frac{17}{4}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Expanding both sides: $ax - 4a + 7 = 5x - 10$. For the equation to have no solution, the coefficients of $x$ must be equal while the constant terms differ. Setting $a = 5$ makes the $x$-coefficients equal on both sides, giving $5x - 20 + 7 = 5x - 10$, which simplifies to $-13 = -10$, a contradiction. Thus $a = 5$ yields no solution. The value $-5$ is a sign error on the coefficient match. The value $3$ comes from partial reasoning such as equating only some terms. The value $\\frac{17}{4}$ comes from incorrectly setting the constant terms equal ($-4a + 7 = -10$) instead of recognizing that no solution requires equal $x$-coefficients with unequal constants.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UIIW31', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{5x^2 + 3x - 11}{x + 2} = ax + b + \\frac{c}{x + 2}$ for constants $a$, $b$, and $c$, what is the value of $a + b + c$?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$-2$"},{"key":"C","text":"$-9$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Performing polynomial long division of $5x^2 + 3x - 11$ by $x + 2$: dividing $5x^2$ by $x$ gives $5x$, and $5x(x + 2) = 5x^2 + 10x$. Subtracting yields $(3x - 10x) - 11 = -7x - 11$. Dividing $-7x$ by $x$ gives $-7$, and $-7(x + 2) = -7x - 14$. Subtracting yields $-11 - (-14) = 3$. So $a = 5$, $b = -7$, $c = 3$, and $a + b + c = 5 - 7 + 3 = 1$. The value $-2$ results from a sign error in the subtraction step. The value $-9$ comes from computing $b + c$ only and omitting $a$. The value $5$ comes from reading only the leading coefficient $a$ without completing the division.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UQ9U7W', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains 7 values: 11, 14, 14, 17, 19, 22, 29. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$17$"},{"key":"C","text":"$18$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'B', NULL, E'With 7 values listed in order, the median is the 4th value. Counting from left: 11, 14, 14, 17 — the 4th value is 17. The distractor 14 selects the mode (most frequent value) instead of the median. The distractor 18 computes the mean of the entire data set ($\\frac{126}{7} = 18$) instead of the median. The distractor 19 selects the 5th value rather than the 4th.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VLVQCD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A health researcher finds that people who drink at least 3 cups of green tea per day have lower rates of heart disease than those who drink no green tea. The study tracked 4,700 volunteers over 6 years and recorded their tea consumption habits and heart disease outcomes. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Drinking green tea causes a reduction in heart disease."},{"key":"B","text":"There is an association between green tea consumption and lower heart disease rates, but causation cannot be established."},{"key":"C","text":"The study proves that not drinking green tea increases heart disease risk."},{"key":"D","text":"The results cannot be generalized because the sample size is too small."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the study tracked volunteers and recorded their existing habits rather than randomly assigning them to drink or not drink green tea, it is an observational study. Observational studies can identify associations but cannot establish causation because confounding variables may explain the observed relationship. Claiming that green tea causes a reduction in heart disease goes beyond what an observational study can support. Claiming the study proves that not drinking green tea increases risk similarly overstates the finding and reverses the framing. A sample of 4,700 tracked over 6 years is a substantial study, so dismissing the results as too small is not justified.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WAOFO1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $XYZ$, the measure of angle $X$ is $58°$ and the measure of angle $Y$ is $71°$. What is the measure, in degrees, of angle $Z$?', NULL, $lyceon_json$[{"key":"A","text":"$49°$"},{"key":"B","text":"$51°$"},{"key":"C","text":"$61°$"},{"key":"D","text":"$129°$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of angles in a triangle is $180°$. Subtracting the two given angles: $180° - 58° - 71° = 51°$. The distractor $49°$ results from a subtraction error. The distractor $61°$ comes from adding $58 + 71 = 129$ but then computing $180 - 129$ incorrectly as $61$. The distractor $129°$ is the sum of the two given angles, not the remaining angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XEW95V', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe calls for $\\frac{7}{4}$ cups of rice to serve 11 people. How many cups of rice are needed to serve 33 people?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{21}{4}$"},{"key":"B","text":"$\\frac{7}{4}$"},{"key":"C","text":"$\\frac{77}{4}$"},{"key":"D","text":"$\\frac{7}{12}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since 33 people is 3 times 11 people, the amount of rice must also be tripled: $\\frac{7}{4} \\times 3 = \\frac{21}{4}$ cups. The distractor $\\frac{7}{4}$ fails to scale the recipe at all. The distractor $\\frac{77}{4}$ incorrectly multiplies by 11 instead of 3. The distractor $\\frac{7}{12}$ incorrectly divides by 3 instead of multiplying.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XYAG9Z', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization surveys a random sample of 1,100 adults in a state and reports that $53\\%$ support a ballot initiative, with a margin of error of $\\pm 2.9\\%$ at a $95\\%$ confidence level. A second poll of 275 adults from the same state finds $48\\%$ support, with a margin of error of $\\pm 5.8\\%$. A journalist concludes that support has declined between the two polls. Which of the following best explains why this conclusion may not be valid?', NULL, $lyceon_json$[{"key":"A","text":"The confidence intervals of the two polls overlap, so the difference in sample proportions may be due to sampling variability."},{"key":"B","text":"The second poll has a larger margin of error, so it must be biased."},{"key":"C","text":"A $95\\%$ confidence level means there is a $5\\%$ chance the true proportion is outside the interval, making any comparison meaningless."},{"key":"D","text":"Neither poll surveyed more than half the state's population, so neither can represent the state."}]$lyceon_json$::jsonb, 'A', NULL, E'The first poll''s confidence interval is approximately $50.1\\%$ to $55.9\\%$, and the second poll''s interval is approximately $42.2\\%$ to $53.8\\%$. These intervals overlap substantially, meaning the observed difference in sample proportions ($53\\%$ vs. $48\\%$) could easily be due to sampling variability rather than a genuine change in opinion. A larger margin of error reflects less precision due to a smaller sample size, not bias. Saying that the $5\\%$ error rate makes any comparison meaningless overstates the limitation; overlapping intervals is the specific reason this comparison is inconclusive. Requiring that more than half the population be surveyed misunderstands how random sampling works.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YB8L0G', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of 600 residents in a county and finds that 246 favor building a new community center. The margin of error is $\\pm 3.7\\%$. Another researcher surveys a random sample of 150 residents from the same county and finds that $44\\%$ favor building the center, with a margin of error of $\\pm 7.4\\%$. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"The first survey's results are more reliable because its confidence interval is narrower."},{"key":"B","text":"The second survey's results are more reliable because it found a higher percentage of support."},{"key":"C","text":"The two surveys contradict each other because their sample proportions differ."},{"key":"D","text":"Neither survey can be used to draw conclusions about the county's residents because neither surveyed all residents."}]$lyceon_json$::jsonb, 'A', NULL, E'The first survey has a sample proportion of $\\frac{246}{600} = 41\\%$ with a margin of error of $\\pm 3.7\\%$, yielding a confidence interval of roughly $37.3\\%$ to $44.7\\%$. The second survey has a confidence interval of roughly $36.6\\%$ to $51.4\\%$. A narrower confidence interval indicates greater precision, making the first survey''s estimate more reliable. A higher percentage of support does not make a survey more reliable; reliability depends on the margin of error. The two surveys do not contradict each other since their confidence intervals overlap. Claiming that no conclusions can be drawn misunderstands the purpose of random sampling and statistical inference.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z688VI', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = 2^{x+1} - 5$. For what value of $x$ does $f(x) = 59$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$5$"},{"key":"C","text":"$6$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting $f(x) = 59$: $2^{x+1} - 5 = 59$, so $2^{x+1} = 64$. Since $64 = 2^6$, we have $x + 1 = 6$, giving $x = 5$. Choosing $4$ results from solving $2^x = 64$ without accounting for the $+1$ in the exponent. Choosing $6$ comes from correctly finding $x + 1 = 6$ but then reporting $x + 1$ rather than $x$. Choosing $3$ results from setting up the equation incorrectly, such as forgetting to add $5$ before solving the exponential.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20N2Z7I', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'A recent geological survey of the Farallon Plate subduction zone revealed unexpectedly high levels of seismic activity at intermediate depths. The survey''s lead author, Dr. Ramesh Iyer, attributes this activity to dehydration embrittlement, a _____ water trapped in mineral structures is released under extreme pressure, generating localized stress changes that can trigger small but measurable earthquakes.', $lyceon_json$[{"key":"A","text":"process, water"},{"key":"B","text":"process in which water"},{"key":"C","text":"process; water"},{"key":"D","text":"process. Water"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence introduces the term "dehydration embrittlement" and then uses the appositive "a process" to begin defining it. The relative pronoun phrase "in which" correctly links the appositive to the clause that explains what happens during the process, forming a single coherent sentence. A comma alone after "process" produces a comma splice by joining the appositive structure to the independent clause "water trapped in mineral structures is released..." without a conjunction or subordinating element. A semicolon after "process" severs the appositive from its defining clause, leaving "dehydration embrittlement, a process" as an incomplete fragment on one side of the semicolon. A period creates the same fragmentation problem, isolating "a process" as an incomplete appositive with no defining information.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21QO6JG', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly weaken the ecologists'' explanation?', E'Ecologists studying the high species diversity of epiphytic orchids in the cloud forests of Oaxaca, Mexico, have proposed that persistent fog immersion is the primary driver of orchid diversification in these habitats. They argue that the constant moisture provided by fog reduces desiccation stress on orchid roots, enabling species with thin, delicate root structures to colonize bark surfaces that would otherwise be inhospitable. Under this explanation, orchid diversity should be highest in forest zones with the most consistent fog exposure and decline sharply in adjacent zones where fog is intermittent.', $lyceon_json$[{"key":"A","text":"Forest zones with intermittent fog exposure harbor nearly as many epiphytic orchid species as zones with constant fog immersion."},{"key":"B","text":"Epiphytic orchid species in cloud forests tend to have thinner roots than terrestrial orchid species in the same region."},{"key":"C","text":"Cloud forests at higher elevations in Oaxaca receive more consistent fog exposure than those at lower elevations."},{"key":"D","text":"Many epiphytic orchid species in Oaxacan cloud forests are not found in lowland tropical forests where rainfall is abundant but fog is rare."}]$lyceon_json$::jsonb, 'A', NULL, E'The ecologists'' explanation predicts that orchid diversity should decline sharply in zones with intermittent fog. A finding that intermittent-fog zones have nearly as many orchid species as constant-fog zones contradicts this prediction, directly weakening the explanation. The finding about thin roots in epiphytic versus terrestrial orchids is consistent with the explanation and does not weaken it. The finding about fog consistency at different elevations describes an environmental gradient but does not address whether diversity correlates with that gradient as predicted. The finding about orchids being absent from fogless lowland forests is consistent with fog being important but does not test the critical prediction about diversity differences between constant and intermittent fog zones.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22HBHCN', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After nearly nine years of fieldwork in the Gobi Desert, paleontologist Tomoko Ueda published a comprehensive monograph on theropod trackways. Dr. Ueda spent three of those years cataloging fossilized footprints at a single _____ documenting over four hundred individual tracks that had never been formally described in the scientific literature.', $lyceon_json$[{"key":"A","text":"site, documenting"},{"key":"B","text":"site; documenting"},{"key":"C","text":"site. Documenting"},{"key":"D","text":"site documenting"}]$lyceon_json$::jsonb, 'A', NULL, E'The phrase "documenting over four hundred individual tracks" is a participial phrase that modifies the subject "Dr. Ueda" and describes an action occurring simultaneously with the cataloging. Because it is not an independent clause, it should be set off with a comma. A semicolon incorrectly treats the participial phrase as an independent clause, but "documenting over four hundred individual tracks..." lacks a subject and finite verb and therefore cannot stand alone. A period creates the same problem, producing a sentence fragment beginning with "Documenting." Omitting punctuation entirely causes the sentence to run together without a clear boundary, obscuring the relationship between the main action and the participial phrase.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW261S4UI', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW276AZ44', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "settled" most nearly mean?', E'In the early nineteenth century, geologists debated whether Earth''s surface features had been shaped by catastrophic events or by slow, continuous processes. By the 1860s, however, accumulating fossil evidence and Charles Lyell''s influential writings had largely settled the question in favor of gradualism, persuading most scientists that landscapes evolved through imperceptible changes over vast stretches of time.', $lyceon_json$[{"key":"A","text":"resolved"},{"key":"B","text":"colonized"},{"key":"C","text":"calmed"},{"key":"D","text":"deposited"}]$lyceon_json$::jsonb, 'A', NULL, E'In this passage, "settled" refers to bringing a debate to a conclusion — that is, resolving the question. The word "colonized" relates to establishing a population in a new territory, which does not fit the context of ending an intellectual dispute. "Calmed" implies soothing emotional agitation, not deciding a scientific controversy. "Deposited" refers to placing or laying down material, a geological sense of "settle" that does not apply to resolving a question.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27Y7VNF', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'When the California condor population plummeted to just twenty-two individuals in 1987, wildlife officials made the controversial decision to capture every remaining bird for a captive breeding program. Critics argued that removing condors from the wild violated the very principle of conservation, while supporters contended that without intervention the species would vanish entirely. Over the following three decades, the breeding program gradually increased the population to over five hundred, and reintroduced condors now soar above the Grand Canyon and the coastal cliffs of Big Sur — though the birds still face persistent threats from lead ammunition and power-line collisions.', $lyceon_json$[{"key":"A","text":"It presents a dilemma, outlines opposing viewpoints, and then describes the outcome of the course of action that was taken."},{"key":"B","text":"It introduces a scientific hypothesis, provides experimental evidence, and then draws a general conclusion about species recovery."},{"key":"C","text":"It describes an animal's habitat, explains why that habitat was destroyed, and then proposes new protective measures."},{"key":"D","text":"It compares two conservation strategies, evaluates each one's effectiveness, and then recommends the superior approach."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first presents the crisis of the condor population drop (a dilemma), then outlines the debate between critics and supporters of captive breeding (opposing viewpoints), and finally describes the population recovery along with ongoing challenges (the outcome). The option about a scientific hypothesis and experimental evidence mischaracterizes the passage''s structure: the text recounts a policy decision and its results, not a controlled experiment. The option about habitat destruction and protective measures misreads the content, since the passage focuses on a captive breeding decision rather than habitat loss or new proposals. The option about comparing two strategies and recommending one overstates the passage''s stance: although the text mentions critics and supporters, it does not formally evaluate two distinct strategies or endorse one over the other.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28CSRD3', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the main purpose of the text?', E'Literary scholars have traditionally treated the nineteenth-century serialized novel as a straightforward precursor to the modern book-length narrative, assuming that authors like Wilkie Collins simply divided pre-planned plots into weekly installments. Recent archival research, however, reveals that Collins frequently revised his outlines in response to reader letters, sales figures, and editorial pressure, sometimes altering major plot points mid-publication. This finding complicates the conventional view by suggesting that serialized fiction was less a fixed literary object than an evolving conversation between author and audience — a dynamic that, some scholars argue, more closely resembles the iterative feedback loops of contemporary digital storytelling than the static artifact of a bound novel.', $lyceon_json$[{"key":"A","text":"To challenge an established scholarly assumption by presenting evidence that supports a more nuanced understanding of a literary form"},{"key":"B","text":"To argue that contemporary digital storytelling has rendered traditional narrative techniques obsolete"},{"key":"C","text":"To provide a comprehensive biography of Wilkie Collins and his contributions to the serialized novel"},{"key":"D","text":"To demonstrate that nineteenth-century readers had more influence over literary markets than publishers did"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage''s main purpose is to challenge the traditional scholarly assumption that serialized novels were simply pre-planned plots divided into installments, using archival evidence to show that the form was far more dynamic and responsive to audience feedback. The option about digital storytelling rendering traditional techniques obsolete overstates the passage''s brief analogy to digital storytelling; the text draws a comparison but never claims traditional techniques are obsolete. The option about providing a comprehensive biography of Collins misreads the passage''s scope: Collins is mentioned as one example supporting a broader argument about serialized fiction, not as the biographical subject. The option about readers having more influence than publishers goes beyond what the text supports; the passage notes reader letters as one of several factors influencing revisions but does not rank audience influence above that of publishers.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AIV46D', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Literary scholar Priya Natarajan has challenged the conventional reading of Bharatendu Harishchandra''s 1880 essay "Bharatvarsh ki Unnati Kaise Ho Sakti Hai" ("How Can India Progress?"). Traditional interpretations treat the essay as a straightforward nationalist call for economic self-sufficiency, emphasizing Harishchandra''s advocacy for indigenous manufacturing. Natarajan argues, however, that such readings overlook the essay''s rhetorical complexity: Harishchandra simultaneously employs satirical exaggeration when describing colonial economic policies and genuine admiration when discussing certain Western educational methods. According to Natarajan, the tension between these two rhetorical modes suggests that Harishchandra was not simply rejecting Western influence but was instead navigating a more ambivalent position—one that selectively embraced foreign innovations while resisting economic exploitation. This nuanced stance, Natarajan contends, has been flattened by later scholars eager to claim Harishchandra as an unqualified precursor to the swadeshi movement.', $lyceon_json$[{"key":"A","text":"Harishchandra's essay has been misunderstood because scholars have failed to recognize that it was intended primarily as satire rather than as a serious political argument."},{"key":"B","text":"Natarajan argues that Harishchandra's essay reflects an ambivalent stance toward Western influence that traditional nationalist readings have oversimplified."},{"key":"C","text":"Natarajan's analysis demonstrates that Harishchandra was more sympathetic to colonial economic policies than previous scholars had acknowledged."},{"key":"D","text":"Traditional scholars have correctly identified Harishchandra's essay as foundational to the swadeshi movement, a view that Natarajan seeks to reinforce with additional evidence."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage centers on Natarajan''s argument that Harishchandra''s essay is more rhetorically complex than the standard nationalist reading allows: it combines satirical critique of colonial economics with genuine admiration for Western education, reflecting ambivalence rather than outright rejection. The option describing Natarajan''s argument about ambivalence and oversimplification captures this central idea. The option claiming the essay was intended primarily as satire overstates one element of Natarajan''s analysis while ignoring the genuine admiration she also identifies. The option suggesting Harishchandra was sympathetic to colonial economic policies distorts the passage—Natarajan says he used satirical exaggeration when describing those policies, indicating critique, not sympathy. The option claiming Natarajan reinforces the swadeshi connection directly contradicts the passage, which states she argues against that flattened reading.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BBSM62', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Archaeologist Fatima El-Tayeb has studied grain storage facilities at the site of ancient Meroe in present-day Sudan, where the Kushite kingdom flourished from roughly 750 BCE to 350 CE. El-Tayeb found that certain large granaries near the royal precinct contained residues of sorghum, millet, and barley mixed together in ratios that do not correspond to the nutritional needs of any known Kushite dietary practice. Moreover, these granaries were sealed with clay impressed with royal insignia, while smaller household granaries in residential areas stored only one grain type each and bore no official markings. El-Tayeb argues that the multi-grain mixtures in the royally sealed granaries were most likely not intended for routine consumption. Instead, she suggests that these stores ________', $lyceon_json$[{"key":"A","text":"served a ceremonial or redistributive function administered by the royal authority, since their contents and official sealing distinguish them from utilitarian household storage."},{"key":"B","text":"were maintained as emergency food reserves for the general population during periods of agricultural shortage, which would explain the variety of grain types preserved."},{"key":"C","text":"reflected the personal dietary preferences of the Kushite royal family, who consumed a wider variety of grains than commoners."},{"key":"D","text":"were accidentally mixed during a period of administrative disorganization near the end of the Kushite kingdom's decline."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage emphasizes two distinguishing features of the royally sealed granaries: multi-grain mixtures that do not match known dietary practices, and official royal sealing absent from household storage. Since El-Tayeb rules out routine consumption, the most logical inference is that the granaries served a non-utilitarian purpose—ceremonial or redistributive—administered by royal authority, which accounts for both the unusual contents and the official markings. The option about emergency reserves explains grain variety but does not account for the royal insignia or why the mixtures fail to match dietary practices. The option about royal dietary preferences contradicts El-Tayeb''s finding that the mixtures do not correspond to any known dietary practice. The option about accidental mixing during decline introduces a speculative historical scenario unsupported by the evidence presented.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EO0XFH', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'A team of marine biologists at the University of Bergen recently documented an unusual behavioral pattern among Arctic cod populations in the Svalbard archipelago. During winter months, when sea ice coverage exceeds 78 percent of the surrounding waters, cod congregate in dense aggregations beneath the ice shelf rather than migrating to deeper, warmer currents as previously assumed. Lead researcher Ingrid Halvorsen noted that the fish appear to exploit a thin layer of relatively warm water trapped between the ice and the colder water below, where small crustaceans also gather, providing an accessible food source. This finding overturns a decades-old model that depicted Arctic cod as obligate deep-water migrants during winter.', $lyceon_json$[{"key":"A","text":"Arctic cod in the Svalbard region remain beneath ice shelves in winter to access food, contradicting earlier assumptions about their seasonal migration."},{"key":"B","text":"Marine biologists have determined that Arctic cod populations are declining because of increased sea ice coverage near Svalbard."},{"key":"C","text":"Small crustaceans trapped beneath Arctic ice provide nutrition for a variety of marine species, including Arctic cod."},{"key":"D","text":"Ingrid Halvorsen's research focuses primarily on the temperature variations in water layers beneath Arctic sea ice."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centrally describes a discovery that Arctic cod stay beneath ice shelves in winter to feed on crustaceans, overturning the previous migration model. The option stating that cod remain beneath ice shelves to access food and that this contradicts earlier assumptions captures this main idea. The option about declining populations introduces a claim not supported by the passage. The option focusing on crustaceans feeding various species elevates a supporting detail to a main idea it does not represent. The option about Halvorsen''s focus on temperature variations mischaracterizes her research, which centers on cod behavior rather than temperature measurement.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FS5QYE', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if accurate, would most directly support the claim made in the text?', E'Some art historians have argued that the Dutch painter Judith Leyster, who was active in the 1630s, deliberately adopted compositional strategies that distinguished her work from that of her contemporary Frans Hals, despite the two painters'' shared use of loose brushwork and lively subject matter. According to this view, Leyster''s compositions are characterized by a more intimate spatial arrangement that draws the viewer into close psychological engagement with the depicted figure—a quality absent from Hals''s more theatrical, outward-facing compositions.', $lyceon_json$[{"key":"A","text":"\"Leyster's figures occupy a compressed pictorial space, frequently making eye contact with the viewer in a manner that creates a sense of private exchange rather than public performance.\""},{"key":"B","text":"\"Both Leyster and Hals employed visible, energetic brushstrokes that became the hallmark of the Haarlem school of painting in the seventeenth century.\""},{"key":"C","text":"\"Leyster's career was cut short after her marriage in 1636, which limited the total number of paintings she produced compared to Hals.\""},{"key":"D","text":"\"Recent infrared analysis reveals that Leyster frequently painted over earlier compositions, suggesting she reused canvases to reduce material costs.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The claim in the passage is that Leyster used compositional strategies creating intimate, psychologically engaging spatial arrangements distinct from Hals''s theatrical style. The quotation about compressed pictorial space and private exchange through eye contact directly illustrates this intimate quality. The quotation about shared brushwork describes a similarity between the two painters, which does not support the claim about Leyster''s deliberate compositional distinction. The quotation about Leyster''s shortened career addresses her output quantity, not her compositional strategies. The quotation about reusing canvases concerns her material practices, not the spatial or psychological qualities of her compositions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
