INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GWO93T', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "tempered" most nearly mean?', E'Historian Elaine Cobham noted that while the Flemish weavers of the fourteenth century introduced remarkably efficient techniques for producing broadcloth, their innovations were tempered by the rigid guild regulations that restricted who could adopt new looms and how many apprentices a master could train. As a result, productivity gains spread far more slowly than the technology itself would have allowed.', $lyceon_json$[{"key":"A","text":"heated"},{"key":"B","text":"moderated"},{"key":"C","text":"angered"},{"key":"D","text":"strengthened"}]$lyceon_json$::jsonb, 'B', NULL, E'In this context, "tempered" means that the innovations were restrained or moderated by guild regulations, which limited how widely new techniques could spread. "Heated" refers to raising the temperature of a material — a metallurgical sense of "temper" that is irrelevant to regulations limiting productivity. "Angered" misapplies the informal meaning of "temper" as irritation; the passage describes regulatory constraint, not emotional provocation. "Strengthened" is the opposite of the intended meaning: the regulations limited rather than enhanced the innovations.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HI2ZOY', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Paleobotanist Selene Okafor has argued that the high concentration of fossilized cycad pollen in Late Triassic sediment layers from the Ischigualasto Formation reflects a humid, subtropical climate in what is now northwestern Argentina. Other researchers have pointed out that cycad pollen is exceptionally durable, meaning it is disproportionately preserved relative to pollen from less hardy plant species. ______ the abundance of cycad pollen in these layers may overstate the actual prevalence of cycads in the ancient ecosystem and thus cannot, on its own, serve as a reliable proxy for paleoclimatic conditions.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"In other words,"},{"key":"C","text":"Regardless,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence after the blank restates the implication of the preceding claim about pollen durability: because cycad pollen is disproportionately preserved, its abundance may be misleading as a climate indicator. This is a reformulation, not a new point, making "In other words," the correct transition. "Moreover," signals an additional, distinct point, but the final sentence does not introduce new evidence—it draws out the consequence already implied by the durability observation. "Regardless," indicates that the upcoming statement holds true irrespective of the preceding information, which mischaracterizes the logical dependence between the durability argument and the conclusion about unreliable proxies. "Specifically," suggests a narrowing from a general claim to a particular detail, but the final sentence broadens the implication rather than specifying a subset of the durability claim.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JAA9CM', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'Coral reefs support roughly one-quarter of all marine species despite covering less than one percent of the ocean floor. ____Marine biologist Anya Petrov has documented how even minor increases in water temperature — as little as 1.5 degrees Celsius above the seasonal average — can trigger mass bleaching events that strip reefs of the symbiotic algae essential to their survival.____ Without these algae, corals lose both their primary food source and the vivid pigmentation that signals a healthy ecosystem.', $lyceon_json$[{"key":"A","text":"It identifies a specific threat to the organisms discussed in the passage."},{"key":"B","text":"It proposes a solution to the environmental problem introduced in the passage."},{"key":"C","text":"It provides background on the evolutionary history of coral species."},{"key":"D","text":"It questions a widely accepted claim about marine biodiversity."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence describes how rising water temperatures cause mass bleaching that damages coral reefs, which identifies a specific threat to the organisms the passage discusses. The option suggesting a solution is incorrect because the sentence describes a danger rather than any remedial measure. The option referencing evolutionary history misreads the content: the sentence discusses a present-day ecological threat, not the origins or evolution of coral species. The option about questioning a biodiversity claim is unsupported; the passage affirms rather than challenges the importance of coral reefs.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KA4QN7', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'At its quarterly meeting, the board of the Ellsworth Land Trust unanimously recommended that the organization''s executive director _____ a formal proposal to acquire the 340-acre parcel of wetlands adjacent to the Kennebec River before the property is listed for commercial development.', $lyceon_json$[{"key":"A","text":"submit"},{"key":"B","text":"submits"},{"key":"C","text":"submitted"},{"key":"D","text":"would submit"}]$lyceon_json$::jsonb, 'A', NULL, E'The verb "recommended" triggers the subjunctive mood in the subordinate "that" clause. In the subjunctive, the verb takes its base form regardless of the subject''s number or person: "recommended that the executive director submit." The indicative form "submits" is incorrect in a subjunctive construction, even though the subject is singular. The past tense "submitted" incorrectly shifts the clause into the indicative past, which does not convey the prescriptive meaning of the recommendation. The conditional "would submit" is a common informal substitution but is not standard in formal written English following verbs of recommendation, and it introduces conditionality where the board''s directive is unconditional.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KHGMV9', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a report on the ecological role of quaking aspens and wants to present a contrast between their above-ground appearance and their underground biology. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M0GBNY', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Neuroscientists at the Karolinska Institute have proposed that the superior spatial memory exhibited by London taxi drivers results not from innate ability but from the intensive navigational training required to earn a taxi license. The researchers hypothesize that years of memorizing thousands of street routes physically enlarges the posterior hippocampus, a brain region associated with spatial navigation. If this hypothesis is correct, the structural changes should be proportional to the duration of navigational experience.', $lyceon_json$[{"key":"A","text":"Taxi drivers who trained for eleven years had larger posterior hippocampi than those who trained for three years."},{"key":"B","text":"Taxi drivers scored higher on verbal memory tests than bus drivers who followed fixed routes."},{"key":"C","text":"The anterior hippocampus was the same size in taxi drivers and in age-matched control subjects."},{"key":"D","text":"Retired taxi drivers reported that they could still navigate London streets accurately from memory."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis predicts that structural changes in the posterior hippocampus should be proportional to years of navigational training. A finding that drivers with more years of training have larger posterior hippocampi directly supports this proportionality claim. The finding about verbal memory tests addresses a different cognitive domain and does not speak to hippocampal enlargement from spatial training. The finding about the anterior hippocampus addresses a different brain region than the one the hypothesis concerns. The finding about retired drivers retaining navigational skill speaks to memory retention but does not provide structural brain evidence relevant to the hypothesis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MJVW0R', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'During the late nineteenth century, Brazilian composer Chiquinha Gonzaga achieved commercial success with popular theater scores and carnival marches at a time when the Brazilian musical establishment regarded such genres as artistically inferior. Conservatory-trained composers who wrote symphonies and operas received institutional patronage, critical attention, and academic appointments, while composers of popular music were largely excluded from these channels of professional recognition. Gonzaga, however, earned her livelihood directly from ticket sales and sheet music royalties, bypassing the institutional gatekeepers entirely. Her financial independence from conservatory networks meant that ________', $lyceon_json$[{"key":"A","text":"she could pursue compositional choices driven by audience reception rather than by the aesthetic priorities of academic critics."},{"key":"B","text":"the conservatory system eventually reformed its criteria to include popular genres in its curriculum."},{"key":"C","text":"her works were technically simpler than those of her conservatory-trained contemporaries."},{"key":"D","text":"she received more critical praise than composers who relied on institutional patronage."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that Gonzaga''s income came from audiences rather than from institutions that valued symphonic and operatic traditions. The logical inference is that this financial independence allowed her to make compositional decisions based on audience preferences rather than academic standards. The option about conservatory reform introduces an outcome the passage does not mention or imply. The option about technical simplicity makes an unsupported assumption about the complexity of her compositions. The option claiming she received more critical praise contradicts the passage, which states that popular composers were excluded from critical recognition channels.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MS3G2H', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'While excavating a Bronze Age settlement near the banks of the River Alde in eastern England, archaeologist Priya Deshpande uncovered a collection of ceramic fragments. Because the fragments exhibited an unusual glazing technique not previously documented in the _____ Deshpande consulted with specialists at the British Museum to determine their origin.', $lyceon_json$[{"key":"A","text":"region, Deshpande"},{"key":"B","text":"region; Deshpande"},{"key":"C","text":"region. Deshpande"},{"key":"D","text":"region Deshpande"}]$lyceon_json$::jsonb, 'A', NULL, E'The clause beginning with "Because" is a dependent (subordinate) clause that cannot stand alone as a sentence. It must be joined to the main clause ("Deshpande consulted with specialists...") with a comma. Using a semicolon or period would incorrectly separate the dependent clause from its main clause, creating a sentence fragment ("Because the fragments exhibited...in the region"). Omitting punctuation entirely produces a run-on that obscures the boundary between the introductory clause and the main clause.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2P576HG', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The veined octopus (Amphioctopus marginatus), found in tropical waters off Indonesia, is one of the few invertebrates observed using tools. Researchers have documented individuals carrying discarded coconut shell halves across the ocean floor and later assembling them into a shelter. This behavior requires the octopus to transport an object that provides no immediate benefit—the shell halves are cumbersome to carry and slow the animal''s movement—in anticipation of a future use. The willingness to accept a present cost for a future gain suggests that the veined octopus ________', $lyceon_json$[{"key":"A","text":"possesses a form of planning behavior previously thought to be limited to vertebrates."},{"key":"B","text":"has developed a symbiotic relationship with the organisms that inhabit coconut shells."},{"key":"C","text":"is more vulnerable to predators than other octopus species that do not use tools."},{"key":"D","text":"prefers coconut shells over other available materials for constructing shelters."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes the octopus accepting a present cost (slow movement) for a future benefit (shelter), which is characteristic of planning behavior. Since the passage notes this is rare among invertebrates, the logical completion is that the octopus demonstrates planning behavior previously associated only with vertebrates. The option about symbiotic relationships introduces a concept entirely unsupported by the passage. The option about predator vulnerability is not implied; the passage does not compare vulnerability across species. The option about preferring coconut shells over other materials addresses material selection, which the passage does not discuss.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PVB9RQ', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "plastic" most nearly mean?', E'Neuroscientist Kenji Furukawa''s 2019 study challenged the long-held view that adult neural pathways are essentially fixed. By exposing subjects to intensive auditory training over eleven weeks, Furukawa demonstrated that the tonotopic maps in the primary auditory cortex remained remarkably plastic, reorganizing their frequency-response boundaries in ways previously documented only in juvenile brains.', $lyceon_json$[{"key":"A","text":"synthetic"},{"key":"B","text":"malleable"},{"key":"C","text":"superficial"},{"key":"D","text":"resilient"}]$lyceon_json$::jsonb, 'B', NULL, E'Here "plastic" describes neural pathways that can be reshaped or reorganized — that is, malleable. The passage emphasizes that brain structures once considered fixed actually changed their boundaries, which is the hallmark of malleability. "Synthetic" refers to something artificially manufactured, which is the common everyday meaning of "plastic" as a material but is irrelevant to brain reorganization. "Superficial" means shallow or surface-level, but the passage describes deep structural reorganization of cortical maps, not a surface-level change. "Resilient" means able to recover from damage, which implies returning to an original state; the passage instead describes pathways that change into new configurations, the opposite of bouncing back.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QV72DQ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2023 study published in the journal Phytochemistry, botanist Lena Korsgaard identified the factor most strongly correlated with flavonoid production in seventeen alpine plant _____ prolonged exposure to ultraviolet radiation at elevations above three thousand meters.', $lyceon_json$[{"key":"A","text":"species: prolonged"},{"key":"B","text":"species, prolonged"},{"key":"C","text":"species; prolonged"},{"key":"D","text":"species. Prolonged"}]$lyceon_json$::jsonb, 'A', NULL, E'The main clause announces that the botanist identified a specific factor, and the phrase after the blank names that factor. Because "prolonged exposure to ultraviolet radiation at elevations above three thousand meters" is a noun phrase acting as an appositive that specifies the identified factor, a colon is the correct mark to introduce it. A comma after "species" would fail to clearly signal the appositive relationship and would leave the sentence''s structure ambiguous. A semicolon is incorrect because what follows the blank is a noun phrase, not an independent clause; a semicolon requires two independent clauses. A period creates a sentence fragment, since "Prolonged exposure to ultraviolet radiation..." lacks a verb and cannot stand alone as a sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R7MPPR', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Hoping to secure additional grant funding for the long-delayed restoration of the Whitfield Covered Bridge, _____ The proposal detailed the bridge''s historical significance, its deteriorating structural elements, and the estimated cost of rehabilitation.', $lyceon_json$[{"key":"A","text":"a comprehensive proposal was drafted by the Claremont Historical Society and submitted to the state preservation office."},{"key":"B","text":"the Claremont Historical Society drafted a comprehensive proposal and submitted it to the state preservation office."},{"key":"C","text":"the state preservation office received a comprehensive proposal from the Claremont Historical Society."},{"key":"D","text":"a comprehensive proposal from the Claremont Historical Society was reviewed by the state preservation office."}]$lyceon_json$::jsonb, 'B', NULL, E'The introductory participial phrase "Hoping to secure additional grant funding" must modify the subject of the main clause. The entity doing the hoping is the Claremont Historical Society, so it must appear as the grammatical subject immediately after the comma. The option beginning with "the Claremont Historical Society drafted a comprehensive proposal" correctly places the society as the subject, aligning it with the participial modifier. The option beginning with "a comprehensive proposal was drafted" creates a dangling modifier, since a proposal cannot hope for anything. Similarly, the option beginning with "the state preservation office received" misattributes the hoping to the preservation office, which is the recipient rather than the initiator. The option beginning with "a comprehensive proposal from the Claremont Historical Society was reviewed" also dangles the modifier, attaching it to "a comprehensive proposal," which again cannot hope.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2S2L06V', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the novelist had originally envisioned a trilogy spanning three decades of political upheaval, she _____ only the first volume before abandoning the project in 2017. The unfinished manuscripts were later donated to the university''s special collections archive.', $lyceon_json$[{"key":"A","text":"completed"},{"key":"B","text":"has completed"},{"key":"C","text":"completes"},{"key":"D","text":"would complete"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence describes a completed action that took place at a specific point in the past ("before abandoning the project in 2017"), so the simple past tense "completed" is correct. The present perfect "has completed" cannot be used with a specific past time reference like "in 2017" because the present perfect connects a past action to the present, whereas this action is firmly situated in the past. The present tense "completes" does not match the past-tense context of the passage. The conditional "would complete" implies a hypothetical or habitual action, neither of which fits the factual narrative of what the novelist actually did.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2S49Z3T', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists at the Falkner Institute recently documented a colony of deep-sea octopuses nesting near hydrothermal vents at depths exceeding 3,200 meters. The octopuses were observed guarding clusters of eggs attached to volcanic rock formations for periods lasting over seventeen months. ______ the researchers noted that the warm water emitted by the vents likely accelerates embryonic development compared to the frigid temperatures of the surrounding ocean floor.', $lyceon_json$[{"key":"A","text":"Notably,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence following the blank adds a noteworthy observation about the warm water''s effect on embryonic development, supplementing the preceding description of nesting behavior. The transition "Notably," correctly signals that what follows is a significant additional detail. "In contrast," incorrectly implies opposition between the two ideas, but the warm-water observation complements rather than contradicts the nesting description. "Nevertheless," suggests a concession or unexpected outcome, yet nothing in the passage sets up a contradiction to overcome. "Consequently," implies a cause-and-effect relationship, but the researchers'' observation about warm water is not a result of the octopuses guarding eggs for seventeen months.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SG6S36', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every autumn, the municipal arboretum in Ashford hosts a festival celebrating native tree species. The collection of heritage oaks, maples, and birches that lines the arboretum''s central _____ a popular destination for families and school groups during the three-week event.', $lyceon_json$[{"key":"A","text":"pathway is"},{"key":"B","text":"pathway are"},{"key":"C","text":"pathway were"},{"key":"D","text":"pathway being"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the sentence is "collection," which is singular, so the verb must also be singular: "is." The intervening prepositional phrase "of heritage oaks, maples, and birches" and the relative clause "that lines the arboretum''s central pathway" do not change the number of the subject. The plural verb "are" incorrectly treats the plural objects of the preposition as the subject. The past tense "were" conflicts with the present-tense context established by "every autumn" and "hosts." The participle "being" lacks a finite verb and produces an incomplete sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
