INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WICG7H', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Throughout the 1930s, the ceramicist Marguerite Friedlaender developed a line of stackable porcelain dinnerware intended for industrial mass production. Her designs emphasized geometric simplicity and functional modularity, features that distinguished them from the ornate tableware popular at the time. ______ Friedlaender''s prototypes were never manufactured at scale during her lifetime, as political upheaval forced her to abandon her workshop and emigrate in 1934.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"For instance,"},{"key":"C","text":"However,"},{"key":"D","text":"Additionally,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage first establishes that Friedlaender developed innovative designs intended for mass production, then reveals that these prototypes were never manufactured at scale. This shift from promising development to unfulfilled outcome represents a contrast, making "However," the logical transition. "Similarly," wrongly suggests the second sentence continues in the same direction as the first, but the failure to reach mass production contradicts the stated intention. "For instance," implies the second sentence illustrates the first, but the abandonment of the workshop is not an example of geometric simplicity or functional modularity. "Additionally," signals a straightforward addition of compatible information, missing the pivotal contrast between design ambition and historical disruption.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X584WF', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Economist Priya Venkataraman has demonstrated that in municipalities where participatory budgeting was adopted between 2009 and 2017, per-capita spending on public transit infrastructure increased by an average of 23 percent. Critics of participatory budgeting, however, note that these same municipalities experienced population growth rates roughly double the national average during that period. ______ the observed increase in transit spending may reflect the demands of a rapidly growing population rather than a distinctive effect of the budgeting model itself.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"That is,"},{"key":"C","text":"On the contrary,"},{"key":"D","text":"Fortunately,"}]$lyceon_json$::jsonb, 'B', NULL, E'The final sentence spells out the implication of the critics'' observation about population growth: the transit spending increase might be attributable to demographic pressure, not the budgeting model. Because this sentence restates and clarifies the critics'' point rather than adding a separate claim, "That is," is the correct transition. "Furthermore," would introduce an entirely new consideration, but the final sentence elaborates on the same population-growth concern already raised. "On the contrary," signals a direct reversal of a preceding assertion, yet the final sentence does not contradict the critics'' point—it extends it. "Fortunately," introduces a positive evaluation that is incongruent with the passage''s analytical tone, and the conclusion that a confounding variable undermines a finding is not presented as a fortunate outcome.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZG14S8', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In a 2023 study published in the journal Pedobiologia, soil ecologist Mariana Delgado-Baquerizo examined the relationship between soil fungal diversity and aboveground plant productivity across 87 dryland ecosystems on six continents. Delgado-Baquerizo found that sites with the highest fungal species richness did not necessarily support the most productive plant communities. Instead, sites with moderate fungal diversity—typically harboring between 140 and 210 distinct fungal taxa—showed the strongest correlation with high plant biomass. The researcher hypothesized that extreme fungal diversity may introduce competitive interactions among fungal species that reduce the efficiency of nutrient cycling, thereby limiting the benefits that plants derive from their fungal symbionts.', $lyceon_json$[{"key":"A","text":"Moderate levels of soil fungal diversity are more strongly associated with plant productivity in drylands than either low or very high fungal diversity."},{"key":"B","text":"Soil fungi in dryland ecosystems compete with plants for nutrients, which limits overall ecosystem productivity."},{"key":"C","text":"Delgado-Baquerizo's study is the first to examine the connection between soil fungi and plant growth across multiple continents."},{"key":"D","text":"The relationship between fungal diversity and plant productivity varies significantly depending on which continent the dryland ecosystem is located on."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage''s central finding is that moderate fungal diversity correlates most strongly with plant productivity, while very high diversity does not produce the best outcomes. The option about moderate fungal diversity levels captures this main idea. The option claiming fungi compete with plants for nutrients misrepresents the passage, which describes competition among fungal species, not between fungi and plants. The option about the study being the first of its kind introduces a claim the passage never makes. The option about continental variation is not supported; the passage mentions six continents as part of the study''s scope but does not discuss variation by continent.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
